package main

import (
	"errors"
	"fmt"
	"io/fs"
	"slices"
	"strings"
)

const noticeHeader = "Third-party licences for the software compiled into line-proton.\n" +
	"Generated by `go run ./internal/tools/licensecheck write`; do not edit by hand.\n"

var rule = strings.Repeat("=", 80)

var grantingPrefixes = []string{"LICENSE", "LICENCE", "COPYING"}

var accompanyingPrefixes = []string{"NOTICE", "PATENTS"}

type moduleOpener func(directory string) fs.FS

type licenseFile struct {
	name string
	text string
}

func render(modules []module, openModule moduleOpener) (string, error) {
	sections := []string{noticeHeader}
	failures := []error{}
	for _, module := range modules {
		section, err := sectionFor(module, openModule(module.directory))
		sections = append(sections, section)
		failures = append(failures, err)
	}
	return strings.Join(sections, ""), errors.Join(failures...)
}

func sectionFor(module module, files fs.FS) (string, error) {
	licenses, err := licenseFilesIn(files)
	if err != nil {
		return "", fmt.Errorf("%s: %w", module.heading(), err)
	}
	if !slices.ContainsFunc(licenses, licenseFile.grantsLicense) {
		return "", fmt.Errorf("%s: no LICENSE, LICENCE or COPYING file in %s", module.heading(), module.directory)
	}
	return "\n" + rule + "\n" + module.heading() + "\n" + rule + "\n" + joinedTexts(licenses), nil
}

func licenseFilesIn(files fs.FS) ([]licenseFile, error) {
	entries, err := fs.ReadDir(files, ".")
	licenses := []licenseFile{}
	failures := []error{err}
	for _, entry := range slices.DeleteFunc(entries, isNotLicenseFile) {
		text, err := fs.ReadFile(files, entry.Name())
		licenses = append(licenses, licenseFile{name: entry.Name(), text: string(text)})
		failures = append(failures, err)
	}
	return licenses, errors.Join(failures...)
}

func isNotLicenseFile(entry fs.DirEntry) bool {
	return !entry.Type().IsRegular() || !hasAnyPrefix(entry.Name(), slices.Concat(grantingPrefixes, accompanyingPrefixes))
}

func (license licenseFile) grantsLicense() bool {
	return hasAnyPrefix(license.name, grantingPrefixes)
}

func hasAnyPrefix(name string, prefixes []string) bool {
	return slices.ContainsFunc(prefixes, func(prefix string) bool {
		return strings.HasPrefix(strings.ToUpper(name), prefix)
	})
}

func joinedTexts(licenses []licenseFile) string {
	texts := []string{}
	for _, license := range licenses {
		texts = append(texts, "\n--- "+license.name+" ---\n\n"+withFinalNewline(license.text))
	}
	return strings.Join(texts, "")
}

func withFinalNewline(text string) string {
	if strings.HasSuffix(text, "\n") {
		return text
	}
	return text + "\n"
}
